:root {
    --xp-face: #ECE9D8;              


    --xp-title-grad: linear-gradient(180deg, #DDE8B6 0%, #A9B97D 7%, #93A564 20%, #96A868 50%, #A9B97D 80%, #A9B97D 90%, #A3B375 95%, #7E9450 100%);
