    --xp-side-box: #F6F6EE;
    --xp-side-edge: #DFE9B5;
    --xp-link: #56662D;
    --xp-link-hover: #86A43A;
    --xp-group-ink: #99540A;         


    --xp-input-edge: #A4B97F;
    --xp-btn-edge: #376206;
    --xp-sel: #93A070;               
    --xp-sel-ink: #FFFFFF;
    --xp-thumb: #A9B98F;             
    --xp-thumb-shadow: inset -3px 0 #95A775, inset 1px 1px #CBD7BA;


    --xp-tb-grad: linear-gradient(180deg, #95A46D 0%, #E7F6BF 3.4%, #DDECB5 6.9%, #C1D099 10.3%, #B4C38C 13.8%, #AAB982 20.7%, #A8B780 31%, #AAB982 44.8%, #B3C289 58.6%, #B9C88F 69%, #BECD94 79.3%, #BAC990 89.7%, #B8C78E 93.1%, #ACBB82 96.6%, #98A76E 100%);
