    --xp-sm-head-edge: #E7F6D7;
    --xp-sm-head-ink: #FFFFFF;
    --xp-sm-head-shadow: #41400A;
    --xp-sm-foot-grad: linear-gradient(180deg, #D7E0AE 0%, #D2DCA8 25%, #CFD9A4 50%, #C4CF97 100%);
